import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.util.Objects;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by ensuring that the resolved
     * file path is strictly within {@code dir}. It also normalises the path,
     * removes query parameters, and guarantees that the parent directories
     * exist.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (may contain sub‑directories, but must
     *             not escape {@code dir}; must not be {@code null})
     * @return a {@link File} instance pointing to a non‑existing file inside
     *         {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        // Basic null checks
        Objects.requireNonNull(dir, "Target directory must not be null");
        Objects.requireNonNull(name, "File name must not be null");

        // Strip query string if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Construct the candidate file
        File file = new File(dir, name);

        // Resolve the canonical path and ensure it stays within the target directory
        try {
            Path targetDir = dir.toPath().toAbsolutePath().normalize();
            Path resolvedPath = file.toPath().toAbsolutePath().normalize();

            if (!resolvedPath.startsWith(targetDir)) {
                throw new IllegalArgumentException(
                        "Attempted to create a file outside the target directory: " + name);
            }
        } catch (IOException e) {
            // Wrap checked exception into unchecked to keep the signature unchanged
            throw new IllegalStateException("Failed to resolve file paths", e);
        }

        // Determine prefix/suffix for unique naming
        int dot = name.lastIndexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? "" : name.substring(dot);

        // Find a unique filename if needed
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        File parent = file.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalStateException("Failed to create directories for: " + parent);
        }

        return file;
    }

    // other methods
}
```

