            return null;
        }

        // If the caller already supplied a Locale, use it directly.
        if (requestedLocale instanceof Locale) {
            return (Locale) requestedLocale;
        }

        // Convert to string and trim whitespace.
        String localeStr = requestedLocale.toString().trim();
        if (localeStr.isEmpty()) {
            return null;
        }

        // Validate against the whitelist pattern.
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
            LOG.warn("Invalid locale format received: '{}'. Ignoring.", localeStr);
            return null;
        }

        // Normalise language code to lower case as required by Locale.
        // Preserve the original case for the country part if present.
