public class Expander {

    // other methods

    /**
     * Safely extracts entries from the supplied archive into {@code targetDirectory}.
     *
     * <p>The method performs strict path validation to prevent path‑traversal attacks:
     * <ul>
     *   <li>All entry names are checked for absolute paths and the presence of {@code ..} components.</li>
     *   <li>Each resolved entry path is normalized and verified to reside within {@code targetDirectory}.</li>
     *   <li>Only canonical paths are compared, ensuring that symbolic links or filesystem quirks cannot bypass the check.</li>
     * </ul>
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to the output stream
     * @param targetDirectory the root directory where entries will be extracted
     * @throws IOException if extraction fails or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical (real) path of the target directory once.
        Path targetPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject absolute paths and names containing backslashes (Windows style).
            if (Paths.get(entryName).isAbsolute() || entryName.contains("\\")) {
                throw new IOException("invalid entry name (absolute or contains backslash): " + entryName);
            }

            // Resolve the entry against the target directory and normalize.
            Path resolvedPath = targetPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!resolvedPath.startsWith(targetPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            // Perform the actual extraction.
            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist.
                if (!Files.isDirectory(resolvedPath)) {
                    Files.createDirectories(resolvedPath);
                }
            } else {
                // Ensure parent directories exist.
                Path parent = resolvedPath.getParent();
                if (parent != null && !Files.isDirectory(parent)) {
                    Files.createDirectories(parent);
                }

                // Write the file contents.
                try (OutputStream out = Files.newOutputStream(resolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
