private int readStored(byte[] buffer, int offset, int length) throws IOException {
    if (buffer == null) throw new NullPointerException("buffer");
    if (offset < 0 || length < 0 || offset + length > buffer.length) throw new IndexOutOfBoundsException();

    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    long csize = current.entry.getSize();
    if (csize < 0) {
        throw new IOException("Invalid entry size: " + csize);
    }

    if (current.bytesRead >= csize) {
        return -1;
    }

    // Ensure we do not attempt to read more than remaining
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    // Fill buffer if empty
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        int l = in.read(buf.array());
        if (l == -1) {
            // Unexpected EOF before reaching expected size
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    int toRead = Math.min(buf.remaining(), length);
    if (toRead > remaining) {
        toRead = (int) remaining;
    }

    if (toRead <= 0) {
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}

