     *         zero if they are equal, or a positive integer if {@code fromVersion} is
     *         greater than {@code toVersion}
     * @throws IllegalArgumentException if either argument is {@code null}, does not
     *                                  contain exactly three components, or contains
     *                                  non‑numeric components
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        // Basic null checks
        if (fromVersion == null || toVersion == null) {
            throw new IllegalArgumentException("Version strings must not be null");
        }

        // Trim whitespace to avoid accidental spaces
        fromVersion = fromVersion.trim();
        toVersion = toVersion.trim();

        // Split into components
        String[] fromArr = fromVersion.split("\\.");
        String[] toArr = toVersion.split("\\.");

        // Ensure exactly three components
        if (fromArr.length != 3 || toArr.length != 3) {
            throw new IllegalArgumentException(
                    "Version strings must have the form 'major.minor.patch'");
        }

        // Parse each component safely
        int fromMajor = parseComponent(fromArr[0], "major", fromVersion);
        int fromMinor = parseComponent(fromArr[1], "minor", fromVersion);
        int fromPatch = parseComponent(fromArr[2], "patch", fromVersion);

        int toMajor = parseComponent(toArr[0], "major", toVersion);
        int toMinor = parseComponent(toArr[1], "minor", toVersion);
        int toPatch = parseComponent(toArr[2], "patch", toVersion);

        // Compare major, then minor, then patch
        int cmp = Integer.compare(fromMajor, toMajor);
        if (cmp != 0) {
            return cmp;
        }
        cmp = Integer.compare(fromMinor, toMinor);
        if (cmp != 0) {
            return cmp;
        }
        return Integer.compare(fromPatch, toPatch);
    }

