    private static int parseComponent(String component, String name, String fullVer) {
        try {
            return Integer.parseInt(component);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException(
                    String.format("Invalid %s component '%s' in version '%s'", name, component, fullVer),
