    /* --------------------------------------------------------------------- */

    /** Set of component classes considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES =
            Collections.unmodifiableSet(new HashSet<Class<?>>(java.util.Arrays.asList(
                    String.class,
                    Integer.class,
                    Long.class,
                    Short.class,
                    Byte.class,
                    Float.class,
                    Double.class,
                    Boolean.class,
                    Character.class,
