     * @param cls the component class to check
     * @return {@code true} if the class is on the whitelist or is a primitive
     */
    private static boolean isSafeComponent(Class<?> cls) {
        return cls.isPrimitive() || SAFE_COMPONENT_TYPES.contains(cls);
