    /* Deserialization logic                                                 */
    /* --------------------------------------------------------------------- */

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(final DefaultJSONParser parser, final Type type, final Object fieldName) {

        /* --------------------------------------------------------------- */
        /* Lexer handling                                                    */
        /* --------------------------------------------------------------- */

        final JSONLexer lexer = parser.lexer;

        // Handle JSON null
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        // Handle JSON string literal -> byte[]
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            final byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        /* --------------------------------------------------------------- */
        /* Resolve component type                                           */
        /* --------------------------------------------------------------- */

        final Class<?> componentClass;
        final Type componentType;

        if (type instanceof GenericArrayType) {
            final GenericArrayType genericArray = (GenericArrayType) type;
            componentType = genericArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                final TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                final Type contextType = parser.getContext().type;

                if (contextType instanceof ParameterizedType) {
                    final ParameterizedType paramType = (ParameterizedType) contextType;
                    final Type rawType = paramType.getRawType();
                    Type actualType = null;

                    if (rawType instanceof Class) {
                        final TypeVariable<?>[] typeParams = ((Class<?>) rawType).getTypeParameters();
                        for (int i = 0; i < typeParams.length; ++i) {
