import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetails;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods

    /**
     * Determines whether the current request is allowed to update the specified SCIM user.
     *
     * <p>This method performs the following checks:
     * <ul>
     *   <li>Validates that the request body contains a well‑formed {@link ScimUser}.</li>
     *   <li>Ensures the authenticated user is present and matches the target user.</li>
     *   <li>Verifies that all mutable fields match the existing values in the database,
     *       preventing unauthorized changes such as email spoofing.</li>
     * </ul>
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the update is permitted; {@code false} otherwise
     * @throws IOException if an I/O error occurs while reading the request body
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Read and parse the request body
        String requestBody = IOUtils.toString(request.getReader());
        if (requestBody == null || requestBody.trim().isEmpty()) {
            return false;
        }

        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Malformed JSON – deny the request
            return false;
        }
        if (scimUserFromRequest == null) {
            return false;
        }

        // 2. Extract the user ID from the request URL
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );
        if (id == null || id.isEmpty()) {
            return false;
        }

        // 3. Resolve the authenticated user’s identity
        String authenticatedUserName = null;

        // Attempt to obtain the principal from the servlet container
        if (request.getUserPrincipal() != null) {
            authenticatedUserName = request.getUserPrincipal().getName();
        }

        // Fallback to Spring Security’s context if available
        if (authenticatedUserName == null) {
            Authentication auth = SecurityContextHolder.getContext().getAuthentication();
            if (auth != null) {
                Object principal = auth.getPrincipal();
                if (principal instanceof UserDetails) {
                    authenticatedUserName = ((UserDetails) principal).getUsername();
                } else if (principal instanceof String) {
                    authenticatedUserName = (String) principal;
                } else {
                    authenticatedUserName = auth.getName();
                }
            }
        }

        if (authenticatedUserName == null) {
            // No authenticated user – deny the request
            return false;
        }

        // 4. Retrieve the existing user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // Target user does not exist – deny the update
            return false;
        }

        // 5. Verify that the authenticated user owns the account being updated
        if (!Objects.equals(authenticatedUserName, scimUserFromDb.getUserName())) {
            return false;
        }

        // 6. Perform field‑by‑field validation
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – allow the update
        return true;
    }

    // other methods
}
